if (st.ok && st.text) {
try {
const j = JSON.parse(st.text);
PRV.ready = new Set(j.renderedChunks || (j.renderedIdx || []).map(i => i + ":0"));
PRV.renderedFiles = j.rendered || 0;
render();
} catch (_) {}
}
const r = await PRV.bridge(PRV.server + "/segments");
if (!r.ok || !r.text) return;
